Let $(G,G_\bullet)$ be a filtered group of degree $k$ and let $K,\Gamma$ be subgroups of $G$. We say that $(K,\Gamma)$ is a \emph{groupable nilpair} in $(G,G_\bullet)$ if any of the following equivalent properties is satisfied:
\begin{enumerate}
    \item For every $x\in G$ and every $i\ge 0$ we have $(Kx\Gamma)\cap(G_ix\Gamma)=(K\cap G_i)x\Gamma$.
    \item For every $x\in G$ and every $i\ge 0$ we have $(Kx\Gamma)\cap(KxG_i)=Kx(\Gamma\cap G_i)$.
\end{enumerate}

\label{thm:inv-double-coset-intro} There exists a family of double-coset nilspaces $\mathcal{N}$, such that for any metrization $D$ of $\mathcal{N}$ the following holds. For any  $\epsilon>0$ and $k\in\mathbb{N}$,  there exists $M_{k,\epsilon}>0$ such that for any finite abelian group $\mathrm{Z}$ and any 1-bounded  function $f:\mathrm{Z}\rightarrow \mathbb{C}$  with $\|f\|_{U^{k+1}(\mathrm{Z})}\ge \epsilon$, for some $i\leq M_{k,\epsilon}$ the triple $(G,K,\Gamma)_{k,i}$ in $\mathcal{N}$  satisfies the following:
\setlength{\leftmargini}{0.7cm}
\begin{enumerate}
    \item there is a polynomial map $g\in \hom(\mathcal{D}_1(\mathbb{Z}^n),G_\bullet)$ such that, letting $\pi_{K,\Gamma}:G\rightarrow K\backslash G/\Gamma$ be the quotient map and $\varphi:\mathbb{Z}^n\rightarrow\mathrm{Z}$ be the natural surjective homomorphism, there exists a morphism $m:\mathcal{D}_1(\mathrm{Z})\rightarrow K\backslash G/\Gamma$ with $\pi_{K,\Gamma}\circ\hspace{-0.02 cm} g = m\circ\hspace{-0.02 cm} \varphi$,
    \item there is a continuous function $F:K\backslash G/\Gamma\rightarrow \mathbb{C}$ with Lipschitz norm $O_{k,\epsilon}(1)$,
\end{enumerate}
and letting $D\subset \mathbb{Z}^n$ be any fundamental domain of $\mathbb{Z}^n/\ker(\varphi)$, we have
\[
\left|\mathbb{E}_{x\in D} f(x) \overline{F\left(K g(x) \Gamma\right)}\right|\gg_{k,\epsilon} 1.
\]

\label{thm:inv-high-ord-latti-intro}
There exists a family of higher-order lattice actions $\mathcal{M}$, such that for any metrization $D$ of $\mathcal{M}$ the following holds.
For any $\epsilon>0$ and $k\in\mathbb{N}$, there exists $N_{k,\epsilon}>0$ such that for any finite abelian group $\mathrm{Z}$  and any 1-bounded function $f:\mathrm{Z}\rightarrow \mathbb{C}$ with $\|f\|_{U^{k+1}(\mathrm{Z})}\ge \epsilon$, for some $i\leq N_{k,\epsilon}$ the pair $(F,\Gamma)_{i,k}$ in $\mathcal{M}$ satisfies the following:
\setlength{\leftmargini}{0.7cm}
\begin{enumerate}
    \item there is a polynomial map $g:\mathbb{Z}^n\rightarrow F$ such that, letting $\pi_{\Gamma}:F\rightarrow F/\Gamma$ be the quotient fibration and $\varphi:\mathbb{Z}^n\rightarrow\mathrm{Z}$ be the natural surjective homomorphism, there exists a morphism $m:\mathcal{D}_1(\mathrm{Z})\rightarrow F/\Gamma$ with $\pi_{\Gamma}\circ\hspace{-0.02 cm} g = m\circ\hspace{-0.02 cm} \varphi$,
    \item there is a continuous function $\phi:F/\Gamma\rightarrow \mathbb{C}$ with Lipschitz norm $O_{k,\epsilon}(1)$,
\end{enumerate}
and letting $D\subset \mathbb{Z}^n$ be any fundamental domain of $\mathbb{Z}^n/\ker(\varphi)$, we have
\[
\left|\mathbb{E}_{x\in D} f(x) \overline{\phi(\pi_\Gamma(g(x)))}\right|\gg_{k,\epsilon} 1.
\]

\label{def:top-nil-open-maps-version}
We say that a nilspace $\mathrm{X}$ is an \textsc{lch}\emph{ nilspace} if $\mathrm{X}$ is a locally-compact Haursdorff second-countable topological space such that the following property holds for every integer $n\geq 0$:
\begin{enumerate}
    \item The cube set $\mathrm{C}^n(\mathrm{X})$ is closed in the product topology on $\mathrm{X}^{\db{n}}$.
    \item The coordinate projection $p^{\db{n}}:\mathrm{C}^n(\mathrm{X})\rightarrow \mathrm{Cor}^n(\mathrm{X})$ is an open map.
\end{enumerate}

\label{lem:eq-def-lch-nil}
Let $\mathrm{X}$ be a $k$-step nilspace endowed with an \textsc{lch} topology. Then $\mathrm{X}$ is an \textsc{lch} nilspace if and only if the following conditions are satisfied:
\begin{enumerate}
    \item For every $n\ge 0$, the cube set $\mathrm{C}^n(\mathrm{X})$ is a closed subset of $\mathrm{X}^{\db{n}}$.
    \item For every $n\in[k]$, the corner completion function $\mathcal{K}_{n+1}:\mathrm{Cor}^{n+1}(\mathrm{X}_n)\rightarrow \mathrm{X}_n$ is continuous, where the canonical factor $\mathrm{X}_n$ is endowed with the quotient topology.
\end{enumerate}

\[
\begin{tikzpicture}
  \matrix (m) [matrix of math nodes,row sep=3em,column sep=4em,minimum width=2em]
  {\mathrm{C}^n(\mathrm{X}) & \hom({\db{n}_{\le k}},\mathrm{X}) & \hom({\db{n}_{\le k}},\mathrm{X}_{k-1}) & \mathrm{C}^n(\mathrm{X}_{k-1}) \\};
  \path[-stealth]
    (m-1-1) edge node [above] {$p_{\db{n}_{\le k}}$} (m-1-2)
    (m-1-2) edge node [above] {$\pi_{k-1}^{\db{n}_{\le k}}$} (m-1-3)
    (m-1-3) edge node [above] {$\mathcal{K}'$} (m-1-4);
\end{tikzpicture}
\]

By \cite[Lemma 4.2]{CGSS} we know that this fiber product is a
$k$-step nilspace (algebraically speaking). Hence, we just have to check that the conditions of Definition \ref{def:top-nil-open-maps-version} are satisfied.

From the continuity of $\varphi$ and $\varphi'$ it is easy to check that the topology on $\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}'$ is also \textsc{lch}. Indeed, this set is a closed subset of $\mathrm{X}\times\mathrm{X}'$, as it is the preimage of the diagonal of $\mathrm{Y}\times \mathrm{Y}$ under the map $(x,x')\mapsto(\varphi(x),\varphi'(x'))$. Similarly, for each $n\geq 0$ the cube set $\mathrm{C}^n(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')$ is closed, since it is $\big[\mathrm{C}^n(\mathrm{X}\times\mathrm{X}')\big]\cap (\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')^{\db{n}}$, which is a closed subset of $(\mathrm{X}\times\mathrm{X}')^{\db{n}}$, so in particular it is a closed subset of $(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')^{\db{n}}$.

Instead of proving the second part of Definition \ref{def:top-nil-open-maps-version} we use Lemma \ref{lem:eq-def-lch-nil} and just check that $\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}'$ satisfies property $(ii)$ in this lemma. By \cite[Proposition A.20]{CGSS-p-hom}, for each $i\in [k]$ the $i$-step characteristic factor of this nilspace is $\mathrm{X}_i\times_{\mathrm{Y}_i}\mathrm{X}'_i$. Also, by the proof of \cite[Proposition A.20]{CGSS-p-hom}, the $i$-th structure group of $\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}'$ is $G_i:=\{(z,z')\in \mathrm{Z}_i(\mathrm{X})\times\mathrm{Z}_i(\mathrm{X}'): \phi_i(z)=\phi'_i(z')\}$ where $\phi_i:\mathrm{Z}_i(\mathrm{X})\rightarrow\mathrm{Z}_i(\mathrm{Y})$ and $\phi'_i:\mathrm{Z}_i(\mathrm{X}')\rightarrow\mathrm{Z}_i(\mathrm{Y})$ are the structure homomorphisms of $\varphi$ and $\varphi'$ respectively (see \cite[Definition 3.3.1]{Cand:Notes1}). To see that part $(ii)$ of Lemma \ref{lem:eq-def-lch-nil} holds for $i=k$, note that the completion function on $\mathrm{Cor}^{k+1}(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')$ is continuous, as it is just the coordinate-wise application of the $(k+1)$-completion functions on $\mathrm{X}$ and $\mathrm{X}'$. For $i< k$, we already have a purely algebraic nilspace isomorphism $(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')_i \rightarrow \mathrm{X}_i \times_{\mathrm{Y}_i} \mathrm{X}_i'$. If we show that this is also a homeomorphism then we will be done, as we can then repeat the preceding argument to obtain the continuity of the completion function. To obtain the homeomorphism property it suffices to show that the quotient topology on $(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')_i$ is equal to the subspace topology on $\mathrm{X}_i \times_{\mathrm{Y}_i} \mathrm{X}_i'$ induced by the product topology on $\mathrm{X}_i\times\mathrm{X}_i$. Note that it suffices to show this for $i=k-1$, as the rest of the cases follow by induction on $k$. Hence, let us consider the following diagram:
\begin{equation}\label{diag:fib-prod-homoeom}
\begin{aligned}[c]
\begin{tikzpicture}
  \matrix (m) [matrix of math nodes,row sep=2em,column sep=4em,minimum width=2em]
  {\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}' & \\
     (\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')_{k-1} & \mathrm{X}_{k-1} \times_{\mathrm{Y}_{k-1}} \mathrm{X}_{k-1}', \\};
  \path[-stealth]
    (m-1-1) edge node [above] {$T$} (m-2-2)
    (m-1-1) edge node [right] {$\pi$} (m-2-1)
    (m-2-1) edge node [above] {$\iota$} (m-2-2);
\end{tikzpicture}
\end{aligned}
\end{equation}

\vspace{-0.3cm}

\noindent where $T(x,x'):=(\pi_{k-1}(x),\pi_{k-1}(x'))$, $\pi$ is the quotient map for the relation $\sim_k$ (see \cite[Definition 3.2.3]{Cand:Notes1}) and $\iota(\pi(x,x'))=(\pi_{k-1}(x),\pi_{k-1}(x'))$. Recall that by \cite[Proposition A.21]{CGSS-p-hom}, $\iota$ is a well-defined bijective morphism. We want to prove that it is a homeomorphism.

We already know that the relation $\sim_k$ on $\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}'$ comes from the continuous action of the group $G_{k}$. Also, using the closure of $\mathrm{C}^n(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')$ it follows that the set $\{((x_0,x_0'),(x_1,x_1'))\in (\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')^2: (x_0,x_0')\sim_k(x_1,x_1')\}$ is closed. Hence we can apply Lemma \ref{lem:quo-by-cont-gr-act} to conclude that the topology on $(\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')_{k-1}$ is \textsc{lch} and, in particular, it is metrizable. Let us now check that $\iota$ is continuous. Indeed, if $U\subset \mathrm{X}_{k-1} \times_{\mathrm{Y}_{k-1}} \mathrm{X}_{k-1}'$ is open, then since $\iota^{-1}(U)=\pi(T^{-1}(U))$, the continuity of $T$ and the openness of $\pi$ imply that $\iota^{-1}(U)$ is open as required. 

To prove that $\iota^{-1}$ is continuous, it suffices to prove that if $(\pi_{k-1}(x_n),\pi_{k-1}(x_n'))$ converges to $(\pi_{k-1}(x),\pi_{k-1}(x'))$ in $\mathrm{X}_{k-1}\times_{\mathrm{Y}_{k-1}}\mathrm{X}_{k-1}'$ as $n\rightarrow\infty$ then $\pi(x_n,x_n')\rightarrow \pi(x,x')$ as $n\rightarrow \infty$. By Lemma \ref{lem:conv-quot}, it suffices to prove that there exists a sequence $(g_n\in G_{k})_{n\in\mathbb{N}}$ such that $(x_n,x_n')+g_n\rightarrow (x,x')$, which we do in the remainder of this proof. 

Note that, without loss of generality, we can assume that $\varphi(x_n)=\varphi'(x_n')$ for all $n\in\mathbb{N}$ (so far we only know that $\varphi_{k-1}(\pi_{k-1}(x_n))=\varphi'_{k-1}(\pi_{k-1}(x_n'))$) and similarly that $\varphi(x)=\varphi'(x')$. Indeed, if this is not the case, say if $\varphi(x)\not=\varphi'(x')$, then since $(\pi_{k-1}(x),\pi_{k-1}(x'))$ is in $\mathrm{X}_{k-1}\times_{\mathrm{Y}_{k-1}}\mathrm{X}_{k-1}'$, we have $\pi_{k-1}(\varphi(x))=\varphi_{k-1}(\pi_{k-1}(x)) = \varphi'_{k-1}(\pi_{k-1}(x'))=\pi_{k-1}(\varphi'(x'))$. In particular, there exists $s\in \mathrm{Z}_k(\mathrm{Y})$ such that $\varphi(x)=\varphi'(x')+s$. Using the surjectivity of $\phi'_k$ we can find some $r\in \mathrm{Z}_k(\mathrm{X}')$ such that $\phi'_k(r)=s$, whence  $\varphi(x)=\varphi'(x'+r)$. With similarly chosen $r_n$ for each $n$, we obtain the claimed additional assumption for $(x_n,x_n'+r_n)$ and $(x,x'+r)$ (and note that $\pi(x_n,x_n'+r_n)=\pi(x_n,x_n')$ and similarly for $(x,x'+r)$, by the invariance of $\pi_{k-1}$ under the action of $\mathrm{Z}_k(\mathrm{X}')$).

By Lemma \ref{lem:conv-quot} in $\mathrm{X}$, there is a sequence $(z_n)_n$ in $\mathrm{Z}_k(\mathrm{X})$ such that $x_n+z_n\rightarrow x$ as $n\rightarrow\infty$ in $\mathrm{X}$. For every $n\in \mathbb{N}$, by the surjectivity of $\phi_k'$ there is $z_n'\in \mathrm{Z}_k(\mathrm{X}')$ such that $(z_n,z_n')\in G_k$. Note that  $\varphi(x+z_n)\rightarrow\varphi(x)$ as $n\rightarrow\infty$ and that $\varphi(x_n+z_n)=\varphi'(x_n'+z_n')$ for all $n\in \mathbb{N}$. Next, by Lemma \ref{lem:conv-quot} applied in $\mathrm{X}'$, for every $n\in \mathbb{N}$ there exists $z_n''\in \mathrm{Z}_k(\mathrm{X}')$ such that $x_n'+z_n'+z_n''\rightarrow x'$ as $n\rightarrow\infty$. We claim that $\phi'_k(z_n'')\rightarrow 0$ as $n\rightarrow \infty$. Indeed $\varphi'(x_n'+z_n'+z_n'')\rightarrow \varphi'(x')=\varphi(x)$ and also $\varphi'(x_n'+z_n'+z_n'')=\varphi'(x_n'+z_n')+\phi_k'(z_n'')=\varphi(x_n+z_n)+\phi_k'(z_n'')$. As $\varphi(x_n+z_n)\rightarrow \varphi(x)$ we get that $\phi'_k(z_n'')\rightarrow 0$ (here we are using Lemma \ref{lem:diff-cont}). Again by Lemma \ref{lem:conv-quot} we get that there exists $z_n^*\in \ker(\phi'_k)$ such that $z_n''-z_n^*\rightarrow 0$ in $\mathrm{Z}_k(\mathrm{X}')$. We claim now that the sequence $(g_n:=(z_n,z_n'+z_n^*)\in G_k)_{n\in\mathbb{N}}$ works, i.e., that $(x_n,x'_n)+g_n\rightarrow (x,x')$. Indeed  $x_n'+z_n'+z_n^*=(x_n'+z_n'+z_n'')+(z_n^*-z_n'')$, where the first summand converges to $x'$ and the second to $0$.

\begin{equation}\label{diag:fib-prod-homoeom}
\begin{aligned}[c]
\begin{tikzpicture}
  \matrix (m) [matrix of math nodes,row sep=2em,column sep=4em,minimum width=2em]
  {\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}' & \\
     (\mathrm{X} \times_{\mathrm{Y}} \mathrm{X}')_{k-1} & \mathrm{X}_{k-1} \times_{\mathrm{Y}_{k-1}} \mathrm{X}_{k-1}', \\};
  \path[-stealth]
    (m-1-1) edge node [above] {$T$} (m-2-2)
    (m-1-1) edge node [right] {$\pi$} (m-2-1)
    (m-2-1) edge node [above] {$\iota$} (m-2-2);
