\label{lem:Taylor-discrete}
Let $k\in \mathbb{N}$. For each $i\in [k]$ let $a_i,b_i\in\mathbb{Z}_{\ge 0}$, and let $F$ be the free nilspace $\big[\prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})\big] \times \big[\prod_{i=1}^k \mathcal{D}_i( \mathbb{R}^{b_i})\big]$. Let $A$ be a discrete finitely generated abelian group, and let $\phi:F\rightarrow \mathcal{D}_k(A)$ be a continuous nilspace morphism. Then for each $m\in \prod_{i=1}^k \mathbb{Z}_{\ge 0}^{a_i}$ with $|(m,0)|_{k,(a_i),(0)}\le k$ there exists a coefficient $g_m\in A$, such that for every $x\in \prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})$ and $y\in \prod_{i=1}^k \mathcal{D}_i( \mathbb{R}^{b_i})$ we have
\begin{equation}\label{eq:Taylor-discrete}
\phi(x,y)=\sum_{m:|(m,0)|_{k,(a_i),(0)}\le k} g_m \binom{(x,y)}{(m,0)}.
\end{equation}
Conversely, every map $\phi$ of the form \eqref{eq:Taylor-discrete} is a continuous morphism $F\rightarrow\mathcal{D}_k(A)$.

\begin{equation}\label{eq:Taylor-discrete}
\phi(x,y)=\sum_{m:|(m,0)|_{k,(a_i),(0)}\le k} g_m \binom{(x,y)}{(m,0)}.
\end{equation}

\label{lem:poly-free-to-R}
Let $k\in \mathbb{N}$. For each $i\in [k]$ let $a_i,b_i\in\mathbb{Z}_{\ge 0}$, and let $F$ be the free nilspace $\big[\prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})\big] \times \big[\prod_{i=1}^k \mathcal{D}_i( \mathbb{R}^{b_i})\big]$. Then for any continuous morphism $\phi:F\rightarrow \mathcal{D}_k(\mathbb{R})$, for each $(m,n)\in (\prod_{i=1}^k \mathbb{Z}_{\ge 0}^{a_i})\times (\prod_{i=1}^k \mathbb{Z}_{\ge 0}^{b_i})$ with $|(m,n)|\leq k$ there is a coefficient $\lambda_{m,n}\in \mathbb{R}$ such that for every $x\in \prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})$ and $y\in \prod_{i=1}^k \mathcal{D}_i( \mathbb{R}^{b_i})$ we have
\begin{equation}\label{eq:poly-free-to-R}
\phi(x,y)=\sum_{(m,n):\,|(m,n)|\le k} \lambda_{m,n} \binom{(x,y)}{(m,n)},
\end{equation}
Conversely, every map $\phi$ of the form \eqref{eq:poly-free-to-R} is a continuous morphism $F\rightarrow\mathcal{D}_k(\mathbb{R})$.

\begin{equation}\label{eq:poly-free-to-R}
\phi(x,y)=\sum_{(m,n):\,|(m,n)|\le k} \lambda_{m,n} \binom{(x,y)}{(m,n)},
\end{equation}

\label{lem:Taylor-cont}
Let $F=\big[\prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})\big] \times \big[\prod_{i=1}^k \mathcal{D}_i( \mathbb{R}^{b_i})\big]$ be a free nilspace and let $\pi:\mathbb{R}\rightarrow\mathbb{T}$ be the canonical quotient homomorphism. A map $\psi:F\rightarrow \mathcal{D}_k(\mathbb{T})$ is a continuous morphism if and only if there is a morphism $\phi:F\rightarrow \mathcal{D}_k(\mathbb{R})$ of the form \eqref{eq:poly-free-to-R} such that
\begin{equation}\label{eq:Taylor-cont}
\psi(x,y)=\pi\circ\hspace{-0.02 cm}\phi(x,y).
\end{equation}

\begin{equation}\label{eq:Taylor-cont}
\psi(x,y)=\pi\circ\hspace{-0.02 cm}\phi(x,y).
\end{equation}

First we address the discrete part, in which $A$ is just a finite abelian group. In this case, letting $r$ be the rank of $A$, the conclusion is the following:
\begin{equation}\label{prop:lift-disc}
 \textrm{there exists a morphism $\psi:F\rightarrow \mathcal{D}_k(\mathbb{Z}^r)$ such that $\phi=\pi\circ\hspace{-0.02 cm}\psi$.}   
\end{equation}
Indeed, it suffices to take the expansion \eqref{eq:Taylor-discrete} for $\phi$, and lift it to a Taylor expansion of a morphism $\psi:F\rightarrow \mathcal{D}_k(B=\mathbb{Z}^r)$ by replacing each coefficient $g_m\in A$ by some $g_m'\in B$ such that $\pi(g_m')=g_m$.

Next we treat the continuous part of the problem, where the image group $A$ is a torus $\mathbb{T}^s$. Letting $\pi:\mathbb{R}\rightarrow\mathbb{T}$ be the canonical quotient homomorphism, the main claim here is that
\begin{equation}\label{prop:lift-cont}
\textrm{there exists a morphism $\psi:F\rightarrow \mathcal{D}_k(\mathbb{R}^s)$ such that $\phi=\pi^s\circ\hspace{-0.02 cm}\psi$.}
\end{equation}
This follows readily by applying Lemma \ref{lem:Taylor-cont} to each of the $s$ coordinate maps of $\phi$ and taking the product of the resulting maps.

The theorem now follows. Indeed,  we can first lift separately the morphisms $\pi_d\circ\hspace{-0.02 cm}\phi$ and $\pi_c\circ\hspace{-0.02 cm}\phi$, using \eqref{prop:lift-disc} and \eqref{prop:lift-cont} respectively, where $\pi_d$ is the coordinate projection from $A$ to its discrete (finite) part $Z$ and $\pi_c$ is the coordinate projection from $A$ to its continuous part $\mathbb{T}^s$. Then we put together the two lifts to obtain $\psi$ (taking the product of the two maps).

\begin{equation}\label{prop:lift-disc}
 \textrm{there exists a morphism $\psi:F\rightarrow \mathcal{D}_k(\mathbb{Z}^r)$ such that $\phi=\pi\circ\hspace{-0.02 cm}\psi$.}   
\end{equation}

\begin{equation}\label{prop:lift-cont}
