\label{lem:nil-pair-good-fil}
Let $(G,G_\bullet)$ be a filtered group of finite degree $k$. Let $K,\Gamma$ be subgroups of $G$. The following statements are equivalent:
\begin{enumerate}[leftmargin=0.7cm]
    \item The filtration $\Gamma_\bullet:=(\Gamma\cap G_i)_{i\ge 0}$ is fiber-transitive on the coset nilspace $K\backslash G$.
    \item For any $x\in G$ and all $i\ge 0$ we have $(Kx\Gamma)\cap(KxG_i)=Kx(\Gamma\cap G_i)$.
\end{enumerate}

\label{lem:sym-nil-pair}
Let $(G,G_\bullet)$ be a degree-$k$ filtered group and let ${\Gamma},K\subset G$ be subgroups. Then the following are equivalent:
\begin{enumerate}
    \item For all $x\in G$ and all $i\ge 0$ we have $(Kx{\Gamma})\cap(G_ix{\Gamma})=(K\cap G_i)x{\Gamma}$.
    \item For all $x\in G$ and all $i\ge 0$ we have $(Kx{\Gamma})\cap(KxG_i)=Kx({\Gamma}\cap G_i)$.
\end{enumerate}

\label{lem_aux-for-dou-coset}
