Let $\mathrm{X}$ be a $k$-step compact nilspace. Then there exists a $k$-step graded pro-free nilspace $(F',(F_i')_{i\in \mathbb{N}})$ such that, letting $G$ be  the degree-$k$ filtered pro-Lie group $\Theta(F',(F_i')_{i\in \mathbb{N}})$, and letting $K$ be the closed pro-Lie subgroup\footnote{Here we took the stabilizer of the constant $\underline{0}$ element, but this can be replaced by any element of $F'=(F_i')_{i\in \mathbb{N}}$.} $\mathrm{Stab}_G(\underline{0})$, there is a fiber-transitive pro-discrete subgroup $\Gamma$ of $G$ such that the following properties hold:
\setlength{\leftmargini}{0.7cm}
\begin{enumerate}
    \item For $j\in \mathbb{N}$ let $p_j':\Theta(F',(F_i')_{i\in \mathbb{N}})\rightarrow \Theta(\prod_{i=1}^jF_i',(F_i')_{i\le j})$ be the projection to the $j$-th factor. Then $p_j'(\Gamma)$ acting on $\prod_{i=1}^jF_i'$ is fiber-transitive, fiber-discrete and fiber-cocompact.
    \item The double-coset nilspace $K\backslash G/\Gamma$ endowed with the quotient topology is isomorphic as a compact nilspace to $\mathrm{X}$.
\end{enumerate}

\label{lem:non-dep-cont-coord}
Let $F=\prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i}\times \mathbb{R}^{b_i})$ be a free nilspace where $a_i,b_i\ge 0$ for $i\in[k]$. Let $A$ be a discrete finitely generated abelian group. Let $\phi:F\rightarrow \mathcal{D}_k(A)$ be a continuous morphism. Then  $\phi(x,y)=\phi(x,0)$
for every $x\in \prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})$ and $y\in \prod_{i=1}^k \mathcal{D}_i(\mathbb{R}^{b_i})$. \footnote{Here we wrote $0$ for the element of $\prod_{i=1}^k \mathcal{D}_i(\mathbb{R}^{b_i})$ with all coordinates equal to zero.}

\label{lem:higher-ab-hom-set}
Let $\mathrm{Z}$, $\mathrm{Z}'$ be abelian groups and let $k,\ell\in\mathbb{N}$. Then
\begin{equation}
 \hom(\mathcal{D}_{\ell}(\mathrm{Z}),\mathcal{D}_k(\mathrm{Z}'))=   \hom(\mathcal{D}_1(\mathrm{Z}),\mathcal{D}_{\lfloor k/\ell\rfloor}(\mathrm{Z}')).
\end{equation}

\begin{equation}
 \hom(\mathcal{D}_{\ell}(\mathrm{Z}),\mathcal{D}_k(\mathrm{Z}'))=   \hom(\mathcal{D}_1(\mathrm{Z}),\mathcal{D}_{\lfloor k/\ell\rfloor}(\mathrm{Z}')).
\end{equation}

\label{thm:Taylor-discrete-app}
Let $F=\prod_{i=1}^k \mathcal{D}_i(\mathbb{Z}^{a_i})$ be a discrete nilspace for some $k\ge 0$ and some integers $a_i\ge 0$, $i\in[k]$. Let $A$ be an abelian group and $\phi:F\rightarrow \mathcal{D}_k(A)$ be a morphism. Then there exists elements $a_m\in A$ for $m= ((m_{i,j})_{j\in a_i})_{i\in[k]} \in \prod_{i=1}^k \mathbb{Z}_{\ge 0}^{a_i}$ such that
\begin{equation}\label{eq:ex-taylor-from-discrete}
\phi(x)=\sum_{|m|\le k}a_m \binom{x}{m} =\sum_{|m|\le k}a_m \prod_{i=1}^k\prod_{j=1}^{a_i} \binom{x_{i,j}}{m_{i,j}}.
\end{equation}

\begin{equation}\label{eq:ex-taylor-from-discrete}
\phi(x)=\sum_{|m|\le k}a_m \binom{x}{m} =\sum_{|m|\le k}a_m \prod_{i=1}^k\prod_{j=1}^{a_i} \binom{x_{i,j}}{m_{i,j}}.
\end{equation}

\[
\partial_{e_{1,1}}^{m'_{1,1}}\cdots \partial_{e_{k,a_k}}^{m'_{k,a_k}}\binom{x}{m}=\partial_{e_{1,1}}^{m'_{1,1}}\cdots \partial_{e_{k,a_k}}^{m'_{k,a_k}}\left(\lambda\prod_{i=1}^k\prod_{j=1}^{a_i} \binom{x_{i,j}}{n_{i,j}}\right) = \lambda\prod_{i=1}^k\prod_{j=1}^{a_i}\partial_{e_{i,j}}^{n'_{i,j}}\binom{x_{i,j}}{m_{i,j}}
\]

Let us denote $D:=\prod_{i=1}^k \mathbb{Z}^{a_i} \times \prod_{i=1}^k  \mathbb{R}^{b_i}$ and $L:=\prod_{i=1}^k \mathbb{Z}_{\ge 0}^{a_i}\times \prod_{i=1}^k \mathbb{Z}_{\ge 0}^{b_i}$.
Similarly as before, given a function $\psi:D\rightarrow \mathbb{T}$ we define its support as follows:
\begin{multline*}
{\rm supp}(\psi):=L\setminus\{(m,n)\in L: \text{for all }(t_{i,\ell})_{(i,\ell)\in[k]\times [b_i]}\in \mathbb{R} \text{ and } (x,y)\in D, \\ \partial_{e_{1,1}}^{m_{1,1}}\cdots \partial_{e_{k,a_k}}^{m_{k,a_k}}\partial_{t_{1,1}w_{1,1}}^{n_{1,1}}\cdots \partial_{t_{k,b_k}w_{k,b_k}}^{n_{k,b_k}}\phi(x)=0 \}
\end{multline*}
where $e_{i,j}\in D$ is everywhere 0 except for the coordinate $(i,j)$ in the discrete part of $D$ (where it is 1) and similarly with $w_{i,\ell}$ for the continuous part. Note that if $\phi:F\rightarrow \mathbb{T}$ is a morphism then ${\rm supp}(\phi)\subset \{(m,n)\in L:|(m,n)|\le k\}$.

We want to prove that if $\psi$ has finite support then $\psi(x,y)=\pi\left(\sum_{(m,n)\in {\rm supp}(\psi)}\lambda_{m,n} \binom{(x,y)}{(m,n)}\right)$ for some coefficients $\lambda_{m,n}\in \mathbb{R}$ (provided that $\psi$ is continuous).

We prove this by induction on the size of ${\rm supp}(\psi)$. Note that if the support of $\psi$ is 0 then this automatically means that the function equals 0, so there is nothing to prove. For the general case, let $(m,n)\in {\rm supp}(\psi)$ be an element such that if $(m',n')\in L$ satisfies $(m,n)<(m',n')$ then $(m',n')\notin {\rm supp}(\psi)$. Assume without loss of generality that $n_{i_0,\ell_0}>0$ for some $(i_0,\ell_0)\in[k]\times [b_i]$. We leave as an exercise to the reader to check the easier case when for some $(i_0,j_0)\in[k]\times[a_i]$ we have $m_{i_0,j_0}>0$. Note that if none of these exists (neither in the continuous part nor in the discrete part), then $\partial_{(u,v)}\psi(x,y)=0$ for all $(u,v)\in D$. Thus $\psi$ in this case is constant and the result follows.

Now, let us consider $(hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y)$. Note that this is a function (in the variables $(x,y)$) from $D$ to $\mathbb{T}$ with support strictly smaller than that of $\psi$. Indeed, note that \[{\rm supp}((hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y))\subset \{(m',n')\in L:(m',n')+w_{i_0,\ell_0}\in {\rm supp}(\psi)\}=:T.\] Note that $T$ is independent of $h$ and that $|T|<|{\rm supp}(\psi)|$. Thus by induction we can write
\begin{equation}\label{eq:form-deri}
(hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y)=\pi\left(\sum_{(m',n')\in T}\lambda_{m,n}(h) \binom{(x,y)}{(m,n)}\right)
\end{equation}
where now the coefficients $\lambda_{m,n}(h)\in \mathbb{R}$ may depend on $h$.

The element $(m^*,n^*):=(m,n)-w_{i_0,\ell_0}$ is in $T$ by definition. Next, we take the derivative of $(hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y)$ as many times as necessary in order to cancel all terms but $\lambda_{m^*,n^*}$. That is,
\begin{equation}\label{eq:proof-fact-free-cont-mor}
\partial_{e_{1,1}}^{m^*_{1,1}}\cdots \partial_{e_{k,a_k}}^{m^*_{k,a_k}}\partial_{w_{1,1}}^{n^*_{1,1}}\cdots \partial_{w_{k,b_k}}^{n^*_{k,b_k}} (hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y) = \pi(\lambda_{m^*,n^*}(h)),
\end{equation}
where $\partial_{e_{i,j}}$ is the operator $(e_{i,j}\cdot \nabla_{(x,y)})$ (and similarly with the $w_{i,\ell}$). Note that the previous equation is true for all $(x,y)\in D$ and all $h\in \mathbb{R}$. Evaluating at $(x,y)=(0,0)$ it follows that $\pi\circ\hspace{-0.02 cm} \lambda_{m^*,n^*}:\mathbb{R}\rightarrow \mathbb{T}$ is a continuous function.

Moreover, we can prove that this function is indeed affine. That is, it is a morphism $\mathcal{D}_1(\mathbb{R})\rightarrow \mathcal{D}_1(\mathbb{T})$. In order to do so, first apply the operator $(z_1\cdot \nabla_h)$ to both sides of \eqref{eq:proof-fact-free-cont-mor}. Note that in the left hand side we end up with an expression that consists of sums and differences of terms of the form
\[
\psi\left((x,y)+hw_{i_0,\ell_0}+\xi z_1 w_{i_0,\ell_0}+\iota_{1,1}e_{1,1}+\cdots+\iota_{k,a_k}e_{k,a_k}+\tau_{1,1}w_{1,1}+\cdots+\tau_{k,b_k}w_{k,b_k}
\right).
\]
Where $\iota_{i,j},\tau_{i,\ell},\xi\in \{0,1\}$ for all $i\in[k]$, $j\in[a_i]$ and $\ell\in[b_i]$. Hence we have the following equality: $(z_1\cdot \nabla_h)\partial_{e_{1,1}}^{m^*_{1,1}}\cdots \partial_{e_{k,a_k}}^{m^*_{k,a_k}}\partial_{w_{1,1}}^{n^*_{1,1}}\cdots \partial_{w_{k,b_k}}^{n^*_{k,b_k}} (hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y) = (z_1\cdot \nabla_h)\pi(\lambda_{m^*,n^*}(h))$, for all $(x,y)\in D$, $h,z_1\in \mathbb{R}$. But making the change of variables $(x,y)\mapsto (x,y)-hw_{i_0,\ell_0}$ we have that the left hand side of the previous equation does not depend on $h$. Therefore applying $(z_2\cdot \nabla_h)$ we get 0 on the  left. Hence
 $0 = (z_2\cdot \nabla_h)(z_1\cdot \nabla_h)\pi(\lambda_{n^*,m^*}(h))$. By Lemma \ref{lem:fact-hom} we have  indeed $\pi(\lambda_{m^*,n^*}(h)) = \pi(\alpha h+\beta)$ for some constants $\alpha,\beta\in \mathbb{R}$. We can use this information to eliminate the term indexed by $(m,n)$ in the support of $\psi$. Indeed, we want to check that
\begin{equation}\label{eq:reduc-degree}
\psi(x,y)-\pi\left(\alpha \binom{(x,y)}{(m,n)}-\beta \binom{(x,y)}{(m^*,n^*)}\right)
\end{equation}
is function on $D$ such that its support is strictly smaller than the support of $\psi$.

In order to prove this, it is enough to check that taking the correct number of derivatives according to $(m,n)$ we have 0. Note that the function $\zeta:\mathbb{R}\rightarrow \mathbb{T}$, $y\mapsto \pi\left(\binom{y}{d}\right)$ satisfies that $\partial_t\zeta(y) = \pi\left(t\binom{y}{d-1}\right)+\textbf{p}(y,t)$ where $\textbf{p}(y,t)$ is a polynomial in $y$ of degree at most $d-2$ and thus it vanishes if we take $d-1$ derivatives on $y$. Using this fact and  \eqref{eq:form-deri} it follows that \eqref{eq:reduc-degree} does not contain $(m,n)$ in its support and so we can conclude the result by induction.

To complete the proof we still need to prove that any function of the form \eqref{eq:Taylor-cont} is a morphism from $F$ to $\mathcal{D}_k(\mathbb{T})$. By Corollary \ref{cor:cont-binom-poly}, any map of the form \eqref{eq:poly-free-to-R} is a morphism from $F$ to $\mathcal{D}_k(\mathbb{R})$. As the quotient map $\pi:\mathbb{R}\rightarrow \mathbb{T}$ is a homomorphism, in particular it is in $\hom(\mathcal{D}_1(\mathbb{R}),\mathcal{D}_1(\mathbb{T}))$ and by Lemma \ref{lem:higher-ab-hom-set} in particular it is in $\hom(\mathcal{D}_k(\mathbb{R}),\mathcal{D}_k(\mathbb{T}))$. The result follows.

\begin{multline*}
{\rm supp}(\psi):=L\setminus\{(m,n)\in L: \text{for all }(t_{i,\ell})_{(i,\ell)\in[k]\times [b_i]}\in \mathbb{R} \text{ and } (x,y)\in D, \\ \partial_{e_{1,1}}^{m_{1,1}}\cdots \partial_{e_{k,a_k}}^{m_{k,a_k}}\partial_{t_{1,1}w_{1,1}}^{n_{1,1}}\cdots \partial_{t_{k,b_k}w_{k,b_k}}^{n_{k,b_k}}\phi(x)=0 \}
\end{multline*}

\begin{equation}\label{eq:form-deri}
(hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y)=\pi\left(\sum_{(m',n')\in T}\lambda_{m,n}(h) \binom{(x,y)}{(m,n)}\right)
\end{equation}

\begin{equation}\label{eq:proof-fact-free-cont-mor}
\partial_{e_{1,1}}^{m^*_{1,1}}\cdots \partial_{e_{k,a_k}}^{m^*_{k,a_k}}\partial_{w_{1,1}}^{n^*_{1,1}}\cdots \partial_{w_{k,b_k}}^{n^*_{k,b_k}} (hw_{i_0,j_0}\cdot \nabla_{(x,y)})\psi(x,y) = \pi(\lambda_{m^*,n^*}(h)),
\end{equation}

\begin{equation}\label{eq:reduc-degree}
\psi(x,y)-\pi\left(\alpha \binom{(x,y)}{(m,n)}-\beta \binom{(x,y)}{(m^*,n^*)}\right)
\end{equation}
